/// <summary>
/// Data contract for the <c>ConDemoNoteReindexService</c> retryable batch operation.
/// </summary>
[DataContractAttribute]
public class ConDemoNoteReindexContract
{
    BatchGroupId    batchGroupId;
}

Method.Source:
/// <summary>
/// Gets or sets the batch group the reindex operation is scheduled into.
/// </summary>
/// <param name = "_batchGroupId">The batch group identifier.</param>
/// <returns>The batch group identifier.</returns>
[DataMemberAttribute('BatchGroupId')]
public BatchGroupId parmBatchGroupId(BatchGroupId _batchGroupId = batchGroupId)
{
    batchGroupId = _batchGroupId;

    return batchGroupId;
}
